+    ASK_USER: { kind: 'alternative', action: 'ASK_USER' },
+    FINISH: { kind: 'alternative', action: 'FINISH' },
+  };
+  const decision = actionAliases[normalized];
+  if (decision?.kind === 'alternative' && context.allowedAlternatives.includes(decision.action)) {
+    return decision;
+  }
+  return undefined;
